function _drawObjectSprite(ctx,cx,cy,color,ts,sprite){const pulse=Math.sin(ts*0.003)*0.5+0.5;const y=cy-2;ctx.fillStyle='rgba(0,0,0,0.15)';ctx.beginPath();ctx.ellipse(cx,cy+1,4,1.5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#5a4a2a';ctx.fillRect(cx-4,y-3,8,5);ctx.fillStyle='#6a5a3a';ctx.fillRect(cx-4.5,y-4,9,2);ctx.fillStyle=color;ctx.fillRect(cx-0.5,y-4,1,5);const sparkAlpha=0.3+pulse*0.4;ctx.fillStyle='rgba(255,235,180,'+sparkAlpha+')';ctx.beginPath();ctx.arc(cx+2,y-5,1,0,Math.PI*2);ctx.fill();}
