function _drawMysterySprite(ctx,cx,cy,color,ts,sprite){const pulse=Math.sin(ts*0.002)*0.4+0.6;const y=cy-6;const bob=Math.sin(ts*0.0015)*2;const glow=ctx.createRadialGradient(cx,y+bob,1,cx,y+bob,9);glow.addColorStop(0,'rgba(120,100,200,'+(0.25*pulse)+')');glow.addColorStop(0.5,'rgba(120,100,200,'+(0.08*pulse)+')');glow.addColorStop(1,'rgba(120,100,200,0)');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(cx,y+bob,9,0,Math.PI*2);ctx.fill();const orbGrad=ctx.createRadialGradient(cx-1,y+bob-1,0,cx,y+bob,3.5);orbGrad.addColorStop(0,'rgba(200,190,255,'+(0.7*pulse)+')');orbGrad.addColorStop(0.6,'rgba(140,120,220,'+(0.5*pulse)+')');orbGrad.addColorStop(1,'rgba(100,80,180,'+(0.2*pulse)+')');ctx.fillStyle=orbGrad;ctx.beginPath();ctx.arc(cx,y+bob,3.5,0,Math.PI*2);ctx.fill();}
