function _drawEnemySprite(ctx,cx,cy,color,ts,sprite){const sway=Math.sin(ts*0.003)*1;const y=cy-5;const aura=ctx.createRadialGradient(cx,cy-2,2,cx,cy-2,12);aura.addColorStop(0,'rgba(60,20,20,0.2)');aura.addColorStop(1,'rgba(60,20,20,0)');ctx.fillStyle=aura;ctx.beginPath();ctx.arc(cx,cy-2,12,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(0,0,0,0.25)';ctx.beginPath();ctx.ellipse(cx,cy+2,5,2,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2a1a1a';ctx.beginPath();ctx.moveTo(cx+sway,y-6);ctx.quadraticCurveTo(cx+6,y,cx+5,y+6);ctx.lineTo(cx-5,y+6);ctx.quadraticCurveTo(cx-6,y,cx+sway,y-6);ctx.closePath();ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.arc(cx-1.5+sway*0.5,y-4,0.8,0,Math.PI*2);ctx.arc(cx+1.5+sway*0.5,y-4,0.8,0,Math.PI*2);ctx.fill();}
