var TERRAIN_NAMES={'.':'Terreno Aberto','T':'Floresta','g':'Vegetação','w':'Água Rasa','W':'Água Profunda','r':'Rochas','R':'Ruínas','M':'Montanha','p':'Trilha','b':'Ossadas','#':'Muro','s':'Areia','m':'Lama','i':'Gelo','v':'Solo Vulcânico','L':'Lava',};var _longPressTimer=null;var _longPressPos=null;function initTerrainTooltip(){if(!_canvas)return;_canvas.addEventListener('touchstart',_onTooltipTouchStart,{passive:true});_canvas.addEventListener('touchend',_onTooltipTouchEnd);_canvas.addEventListener('touchmove',_onTooltipTouchMove,{passive:true});}
